// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.roll(1);
        vm.warp(100);

        vm.deal(address(this), 0 ether);
        (bool ok1, ) = address(c).call{value: 0 ether}("");

        vm.deal(address(this), 10 ether);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        assertTrue(ok2 == true, "Second call should succeed on reference");
    }
}
